\set ON_ERROR_STOP on
SET ROLE hospital_owner;
SET search_path=pg_catalog,ext,public;
BEGIN;
CREATE TABLE org.organization(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,code text NOT NULL UNIQUE,name ref.nonblank_text NOT NULL,kind text NOT NULL CHECK(kind IN('hospital','clinic','laboratory')),active boolean NOT NULL DEFAULT true);
CREATE TABLE org.site(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id bigint NOT NULL REFERENCES org.organization,code text NOT NULL UNIQUE,name text NOT NULL,time_zone text NOT NULL DEFAULT 'Asia/Qyzylorda',address_text text NOT NULL,location ext.geography(Point,4326),UNIQUE(id,organization_id));
CREATE TABLE org.department(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,site_id bigint NOT NULL REFERENCES org.site,code text NOT NULL UNIQUE,name text NOT NULL,kind text NOT NULL CHECK(kind IN('clinical','diagnostic','support')),active boolean NOT NULL DEFAULT true,UNIQUE(id,site_id));
CREATE TABLE org.room(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,department_id bigint NOT NULL REFERENCES org.department,code text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN('ward','consultation','procedure','laboratory','operating','storage')),floor_number smallint NOT NULL,UNIQUE(department_id,code),UNIQUE(id,department_id));
CREATE TABLE org.bed(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,room_id bigint NOT NULL REFERENCES org.room,code text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true,bed_type text NOT NULL CHECK(bed_type IN('standard','icu','isolation','pediatric')));
CREATE TABLE org.staff(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staff_number text NOT NULL UNIQUE,display_name text NOT NULL,profession text NOT NULL CHECK(profession IN('physician','nurse','technician','pharmacist','administrator')),specialty_concept_id integer REFERENCES ref.concept,active boolean NOT NULL DEFAULT true);
CREATE TABLE org.staff_department(staff_id bigint NOT NULL REFERENCES org.staff,department_id bigint NOT NULL REFERENCES org.department,valid_during daterange NOT NULL CHECK(NOT isempty(valid_during)),is_primary boolean NOT NULL DEFAULT false,PRIMARY KEY(staff_id,department_id,valid_during),EXCLUDE USING gist(staff_id WITH =,department_id WITH =,valid_during WITH &&));
CREATE TABLE org.credential(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staff_id bigint NOT NULL REFERENCES org.staff,credential_type text NOT NULL,identifier text NOT NULL UNIQUE,valid_during daterange NOT NULL CHECK(NOT isempty(valid_during)),issuer text NOT NULL,is_synthetic boolean NOT NULL DEFAULT true);
CREATE TABLE org.device(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,department_id bigint NOT NULL REFERENCES org.department,asset_tag text NOT NULL UNIQUE,name text NOT NULL,modality text,serial_number text UNIQUE,active boolean NOT NULL DEFAULT true,next_maintenance_on date);
CREATE TABLE mpi.patient(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,mrn text NOT NULL UNIQUE,family_name ref.nonblank_text NOT NULL,given_name ref.nonblank_text NOT NULL,birth_date date NOT NULL CHECK(birth_date BETWEEN DATE '1850-01-01' AND DATE '2100-01-01'),administrative_gender text NOT NULL CHECK(administrative_gender IN('female','male','other','unknown')),deceased_at timestamptz,active boolean NOT NULL DEFAULT true,is_synthetic boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),CHECK(deceased_at IS NULL OR deceased_at::date>=birth_date));
CREATE TABLE mpi.identifier(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,system_uri text NOT NULL,value ref.nonblank_text NOT NULL,valid_during daterange NOT NULL DEFAULT daterange(NULL,NULL,'[)'),UNIQUE(system_uri,value),CHECK(NOT isempty(valid_during)));
CREATE TABLE mpi.address(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,use_code text NOT NULL CHECK(use_code IN('home','temporary','work')),country_code char(2) NOT NULL,city text NOT NULL,line_text text NOT NULL,postal_code text,location ext.geography(Point,4326),valid_during daterange NOT NULL CHECK(NOT isempty(valid_during)));
CREATE TABLE mpi.contact(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,system text NOT NULL CHECK(system IN('phone','email')),value text NOT NULL,use_code text NOT NULL,rank smallint NOT NULL CHECK(rank>0),UNIQUE(patient_id,system,rank));
CREATE TABLE mpi.related_person(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,display_name text NOT NULL,relationship text NOT NULL,contact_text text,is_emergency_contact boolean NOT NULL DEFAULT false);
CREATE TABLE mpi.consent(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,scope text NOT NULL CHECK(scope IN('treatment','data_exchange','research')),status text NOT NULL CHECK(status IN('active','revoked','expired')),valid_during tstzrange NOT NULL CHECK(NOT isempty(valid_during)),recorded_at timestamptz NOT NULL,recorded_by bigint NOT NULL REFERENCES org.staff,document_reference text,UNIQUE(id,patient_id));
CREATE TABLE mpi.merge_history(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,source_patient_id bigint NOT NULL REFERENCES mpi.patient,target_patient_id bigint NOT NULL REFERENCES mpi.patient,merged_at timestamptz NOT NULL,merged_by bigint NOT NULL REFERENCES org.staff,reason ref.nonblank_text NOT NULL,CHECK(source_patient_id<>target_patient_id),UNIQUE(source_patient_id));
CREATE TABLE iam.application_user(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,database_principal name NOT NULL UNIQUE,staff_id bigint UNIQUE REFERENCES org.staff,display_name text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE iam.business_role(code text PRIMARY KEY,name text NOT NULL);
CREATE TABLE iam.user_role(user_id bigint NOT NULL REFERENCES iam.application_user,role_code text NOT NULL REFERENCES iam.business_role,PRIMARY KEY(user_id,role_code));
CREATE TABLE iam.access_grant(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES iam.application_user,patient_id bigint NOT NULL REFERENCES mpi.patient,purpose text NOT NULL CHECK(purpose IN('treatment','registration','billing')),valid_during tstzrange NOT NULL CHECK(NOT isempty(valid_during)),granted_by bigint NOT NULL REFERENCES iam.application_user,reason text NOT NULL,UNIQUE(user_id,patient_id,purpose,valid_during));
CREATE TABLE iam.break_glass(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES iam.application_user,patient_id bigint NOT NULL REFERENCES mpi.patient,reason ref.nonblank_text NOT NULL,valid_during tstzrange NOT NULL CHECK(NOT isempty(valid_during) AND NOT lower_inf(valid_during) AND NOT upper_inf(valid_during) AND upper(valid_during)-lower(valid_during)<=INTERVAL '1 hour'),approved_by bigint NOT NULL REFERENCES iam.application_user,reviewed_at timestamptz,CHECK(user_id<>approved_by));
INSERT INTO ops.schema_migration VALUES('01',clock_timestamp(),'Organization, master patient index and identity');
COMMIT;
